import unittest

from solution import reconcile_records


A = "a" * 64
B = "b" * 64
C = "c" * 64
D = "d" * 64


class ReconcileRecordsTests(unittest.TestCase):
    def test_reconciliation_order_and_digest_replacement(self):
        expected = {
            "changed": {"digest": A},
            "missing": {"digest": B},
            "same": {"digest": C},
        }
        observed = {
            "extra": {"digest": D, "value": 1},
            "same": {"digest": C, "value": 2},
            "changed": {"digest": B, "value": 3},
        }
        result = reconcile_records(expected, observed)
        self.assertEqual(list(result.keys()), ["records", "mismatches"])
        self.assertEqual(list(result["records"].keys()), ["extra", "same", "changed"])
        self.assertEqual(result["records"]["extra"], {"digest": D, "value": 1})
        self.assertEqual(result["records"]["same"]["digest"], C)
        self.assertEqual(result["records"]["changed"]["digest"], A)
        self.assertNotIn("missing", result["records"])
        self.assertEqual(result["mismatches"], ["changed", "missing"])

    def test_empty_inputs(self):
        self.assertEqual(reconcile_records({}, {}), {
            "records": {}, "mismatches": []
        })

    def test_result_is_deep_copied_and_inputs_are_unchanged(self):
        expected = {"x": {"digest": A, "unused": {"k": [1]}}}
        observed = {
            "x": {"digest": B, "nested": {"items": [1, {"v": 2}]}},
            "extra": {"digest": C, "data": [[3]]},
        }
        expected_before = {
            "x": {"digest": A, "unused": {"k": [1]}}
        }
        observed_before = {
            "x": {"digest": B, "nested": {"items": [1, {"v": 2}]}},
            "extra": {"digest": C, "data": [[3]]},
        }
        result = reconcile_records(expected, observed)
        result["records"]["x"]["nested"]["items"][1]["v"] = 99
        result["records"]["extra"]["data"][0].append(4)
        result["mismatches"].append("fake")
        self.assertEqual(expected, expected_before)
        self.assertEqual(observed, observed_before)

    def test_each_call_returns_independent_mutable_data(self):
        observed = {"x": {"digest": A, "nested": [1]}}
        first = reconcile_records({}, observed)
        second = reconcile_records({}, observed)
        first["records"]["x"]["nested"].append(2)
        first["mismatches"].append("x")
        self.assertEqual(second, {
            "records": {"x": {"digest": A, "nested": [1]}},
            "mismatches": [],
        })

    def test_top_level_arguments_and_keys_are_validated(self):
        with self.assertRaises(TypeError):
            reconcile_records([], {})
        with self.assertRaises(TypeError):
            reconcile_records({}, [])
        for bad_key in ("", 1, None):
            with self.subTest(bad_key=bad_key):
                with self.assertRaises((TypeError, ValueError)):
                    reconcile_records({bad_key: {"digest": A}}, {})
                with self.assertRaises((TypeError, ValueError)):
                    reconcile_records({}, {bad_key: {"digest": A}})

    def test_record_shape_and_digest_are_validated_in_both_inputs(self):
        malformed_records = [
            None,
            [],
            {},
            {"digest": 1},
            {"digest": "a" * 63},
            {"digest": "A" * 64},
            {"digest": "g" * 64},
        ]
        for record in malformed_records:
            with self.subTest(record=record, side="expected"):
                with self.assertRaises((TypeError, ValueError)):
                    reconcile_records({"x": record}, {})
            with self.subTest(record=record, side="observed"):
                with self.assertRaises((TypeError, ValueError)):
                    reconcile_records({}, {"x": record})


if __name__ == "__main__":
    unittest.main()

